namespace Evidgate.Modules.Usage.Domain;

/// <summary>
/// One row the ledger is about to insert (12.3.1 §4), already validated and with its app-generated identity
/// (UUIDv7, so <c>created_at</c> order and <c>id</c> order agree). The price columns are absent on purpose: 12.3.1-T1
/// writes <c>price_ref</c>, <c>amount</c> and <c>currency</c> as null until 12.3.1-T3 resolves prices (DECISIONS O5,
/// ruling T60 — an unpriced row is null, never zero).
/// </summary>
/// <param name="Id">The row identity, generated by the module.</param>
/// <param name="ProjectId">The project, or null for an org-level metric.</param>
/// <param name="Metric">The column value of the metric (the wire name).</param>
/// <param name="Quantity">The measured amount.</param>
/// <param name="Unit">The unit of <paramref name="Quantity"/>.</param>
/// <param name="Period">The <c>YYYY-MM</c> billing period.</param>
/// <param name="BillingKey">The per-org dedupe key.</param>
/// <param name="OccurredAt">When the metered work happened.</param>
/// <param name="PayloadHash">The canonical hash of the billable payload this key claims.</param>
internal sealed record PendingUsageEntry(
    Guid Id,
    Guid? ProjectId,
    string Metric,
    decimal Quantity,
    string Unit,
    string Period,
    string BillingKey,
    DateTimeOffset OccurredAt,
    string PayloadHash);
